## Phase 1: Types, Config & Service (Red → Green)

### Phase 1 Tests — Write First

**File:** `src/node/services/__tests__/devToolsService.test.ts`

```typescript
describe("DevToolsService", () => {
  // Setup: create a real service instance with a temp dir (same pattern as createTestHistoryService)
  let service: DevToolsService;
  let tmpDir: string;

  beforeEach(() => {
    tmpDir = mkdtempSync(path.join(tmpdir(), "devtools-test-"));
    const config = createTestConfig({ sessionsDir: tmpDir });
    service = new DevToolsService(config);
  });

  describe("when disabled", () => {
    it("createRun is a no-op — getRuns returns empty", async () => {
      // config.llmDebugLogsEnabled returns false
      await service.createRun("ws-1", { id: "run-1", workspaceId: "ws-1", startedAt: "..." });
      const runs = await service.getRuns("ws-1");
      expect(runs).toEqual([]);
    });

    it("createStep is a no-op", async () => {
      await service.createStep("ws-1", makeStep({ id: "s-1", runId: "run-1" }));
      const detail = await service.getRunWithSteps("ws-1", "run-1");
      expect(detail).toBeNull();
    });

    it("does not write devtools.jsonl to disk", async () => {
      await service.createRun("ws-1", makeRun("run-1"));
      const filePath = path.join(tmpDir, "ws-1", "devtools.jsonl");
      expect(existsSync(filePath)).toBe(false);
    });
  });

  describe("when enabled", () => {
    beforeEach(() => {
      // Override config to return llmDebugLogsEnabled = true
    });

    it("createRun stores a run, getRuns returns it as a summary", async () => {
      await service.createRun("ws-1", makeRun("run-1"));
      const runs = await service.getRuns("ws-1");
      expect(runs).toHaveLength(1);
      expect(runs[0].id).toBe("run-1");
      expect(runs[0].stepCount).toBe(0);
      expect(runs[0].isInProgress).toBe(false);
    });

    it("createStep stores a step, getRunWithSteps returns it", async () => {
      await service.createRun("ws-1", makeRun("run-1"));
      await service.createStep("ws-1", makeStep({ id: "s-1", runId: "run-1", stepNumber: 1 }));
      const detail = await service.getRunWithSteps("ws-1", "run-1");
      expect(detail).not.toBeNull();
      expect(detail!.steps).toHaveLength(1);
      expect(detail!.steps[0].id).toBe("s-1");
    })
